def generate(seed):
    r = random.Random(seed)
    for _ in range(600):
        A = r.sample("ABCDEFGHJKLMNPRSTUVW", 6)
        pat = [1] * r.randint(2, 3)                       # left end anchored (>=2 books)
        while len(pat) < 32:
            pat += [0] * (1 if r.random() < 0.68 else 2)  # gaps: one slot, or two (decoy)
            pat += [1] * r.choice((1, 1, 2, 2, 3))
        pat += [0] * (1 if r.random() < 0.68 else 2)
        pat += [1] * r.randint(2, 3)                      # right end anchored (>=2 books)
        W = len(pat)
        if not (34 <= W <= 42):
            continue
        g = lambda j: 0 <= j < W and not pat[j]
        cand, iso, far = [], [], []
        for i in range(W):
            if not pat[i]:
                continue
            d = g(i + 1) - g(i - 1)
            if not d:
                if g(i + 1) and g(i - 1):
                    iso.append(i)                         # gaps both sides: nothing tips it
            elif 0 <= i + 2 * d < W and pat[i + 2 * d]:
                cand.append((i, d))                       # a book within reach across the gap
            else:
                far.append(i)                             # two-slot gap: nothing within reach
        if not (10 <= len(cand) <= 18) or len(iso) < 2 or len(far) < 2:
            continue
        L = "".join(r.choice(A) if pat[j] else "." for j in range(W))
        hmax = r.choice((4, 5, 6))
        H = [r.randint(1, hmax) if pat[j] else 0 for j in range(W)]
        # plant one facing pair at EQUAL height: two books either side of a one-slot gap,
        # both still standing, so the near-miss ">=" is visibly wrong in every drawing.
        i0, d0 = cand[r.randrange(len(cand))]
        H[i0] = H[i0 + 2 * d0] = r.randint(2, hmax)
        tip = lambda: [i for i, d in cand if H[i + 2 * d] > H[i]]
        if r.random() < 0.075:
            for _ in range(80):        # the foothold: ~15 % of shelves have nothing falling
                if not tip():
                    break
                for i, d in cand:
                    if H[i + 2 * d] > H[i]:
                        H[i + 2 * d] = r.randint(1, H[i])
        n = len(tip())
        if n and not (4 <= n <= 9):
            continue
        M = max(H) + 1
        P = [[" "] * W for _ in range(M)]
        P[M - 1] = list(L)
        for i in range(W):
            for t in range(1, H[i]):
                P[M - 1 - t][i] = L[i]
            if H[i]:
                P[M - 1 - H[i]][i] = "_"
        return "\n".join("".join(x).rstrip() for x in P) + "\n" + "=" * W + "\n" + str(n) + " fall"
    return FB

